render:
const { root, params, progress, time, width, height } = ctx;
const canvas = root.querySelector('#sphere-canvas');
if (!canvas) return;

if (canvas.width !== width || canvas.height !== height) {
  canvas.width = width;
  canvas.height = height;
}

const c = canvas.getContext('2d');
const centerText = params.center_text || "";
const textSize = params.text_size || 32;
const textColor = params.text_color || "#FF3366";
const numPoints = params.point_density || 80;
const basePointSize = params.point_size || 4;
const baseLineWidth = params.line_width || 2.5;
const rotDir = params.rot_direction || "Horizontal (Izquierda -> Derecha)";
const rotSpeed = (params.rot_speed || 10) * 0.1;
const primaryColor = params.primary_color || "#FF3366";
const bgColor = params.bg_color || "#FFFFFF";
const glowBlur = params.glow_intensity || 15;
const maxDist = params.conn_distance || 90;
const radiusPct = (params.sphere_radius || 35) / 100;
const useDepth = (params.show_depth || "Sí") === "Sí";

// Limpiar fondo
c.fillStyle = bgColor;
c.fillRect(0, 0, width, height);

const cx = width / 2;
const cy = height / 2;
const radius = Math.min(width, height) * radiusPct;

// 1. DIBUJAR TEXTO EN EL CENTRO
if (centerText.trim() !== "") {
  c.save();
  c.font = `bold ${textSize}px system-ui, -apple-system, sans-serif`;
  c.textAlign = "center";
  c.textBaseline = "middle";
  c.fillStyle = textColor;
  c.shadowColor = textColor;
  c.shadowBlur = glowBlur;
  c.fillText(centerText, cx, cy);
  c.restore();
}

// Generación determinista de puntos en superficie de la esfera (Fibonacci Sphere)
const points = [];
const phi = (1 + Math.sqrt(5)) / 2;

for (let i = 0; i < numPoints; i++) {
  const y = 1 - (i / (numPoints - 1)) * 2;
  const radiusAtY = Math.sqrt(1 - y * y);
  const theta = 2 * Math.PI * i / phi;

  const x = Math.cos(theta) * radiusAtY;
  const z = Math.sin(theta) * radiusAtY;

  const isHighlight = (i % 7 === 0);

  points.push({ x: x * radius, y: y * radius, z: z * radius, isHighlight });
}

let angleX = 0;
let angleY = 0;
let angleZ = 0;

const t = time * rotSpeed;

if (rotDir === "Horizontal (Izquierda -> Derecha)") {
  angleY = t;
} else if (rotDir === "Horizontal (Derecha -> Izquierda)") {
  angleY = -t;
} else if (rotDir === "Vertical (Arriba -> Abajo)") {
  angleX = t;
} else {
  angleX = t * 0.7;
  angleY = t * 0.7;
  angleZ = t * 0.3;
}

const cosX = Math.cos(angleX), sinX = Math.sin(angleX);
const cosY = Math.cos(angleY), sinY = Math.sin(angleY);
const cosZ = Math.cos(angleZ), sinZ = Math.sin(angleZ);

const projected = points.map(p => {
  let y1 = p.y * cosX - p.z * sinX;
  let z1 = p.y * sinX + p.z * cosX;
  let x1 = p.x;

  let x2 = x1 * cosY + z1 * sinY;
  let z2 = -x1 * sinY + z1 * cosY;
  let y2 = y1;

  let x3 = x2 * cosZ - y2 * sinZ;
  let y3 = x2 * sinZ + y2 * cosZ;
  let z3 = z2;

  const perspective = 600;
  const scale = perspective / (perspective + z3);
  const projX = cx + x3 * scale;
  const projY = cy + y3 * scale;

  const depthFactor = Math.max(0.1, Math.min(1, (z3 + radius) / (2 * radius)));

  return {
    x: projX,
    y: projY,
    z: z3,
    scale,
    depth: depthFactor,
    isHighlight: p.isHighlight
  };
});

projected.sort((a, b) => a.z - b.z);

function hexToRgb(hex) {
  let c = hex.replace('#', '');
  if (c.length === 3) c = c.split('').map(x => x + x).join('');
  const num = parseInt(c, 16);
  return { r: (num >> 16) & 255, g: (num >> 8) & 255, b: num & 255 };
}

const rgb = hexToRgb(primaryColor);

// 2. DIBUJAR LÍNEAS DE CONEXIÓN
for (let i = 0; i < projected.length; i++) {
  const p1 = projected[i];
  for (let j = i + 1; j < projected.length; j++) {
    const p2 = projected[j];
    const dx = p1.x - p2.x;
    const dy = p1.y - p2.y;
    const dist = Math.sqrt(dx * dx + dy * dy);

    if (dist < maxDist) {
      const alphaDist = 1 - (dist / maxDist);
      const avgDepth = useDepth ? (p1.depth + p2.depth) / 2 : 1;
      const finalAlpha = Math.max(0, Math.min(1, alphaDist * avgDepth * 0.7));

      c.strokeStyle = `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${finalAlpha})`;
      c.lineWidth = (useDepth ? avgDepth : 1) * baseLineWidth;
      c.beginPath();
      c.moveTo(p1.x, p1.y);
      c.lineTo(p2.x, p2.y);
      c.stroke();
    }
  }
}

// 3. DIBUJAR NODOS / PUNTOS
projected.forEach(p => {
  const pSize = useDepth ? basePointSize * (0.5 + p.depth * 0.8) : basePointSize;
  const pAlpha = useDepth ? Math.max(0.2, p.depth) : 1;

  c.save();
  c.fillStyle = `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${pAlpha})`;
  c.shadowColor = primaryColor;
  c.shadowBlur = glowBlur * (useDepth ? p.depth : 1);

  if (p.isHighlight) {
    c.beginPath();
    c.arc(p.x, p.y, pSize * 2.2, 0, Math.PI * 2);
    c.fillStyle = `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${pAlpha * 0.25})`;
    c.fill();
  }

  c.beginPath();
  c.arc(p.x, p.y, pSize, 0, Math.PI * 2);
  c.fillStyle = `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${pAlpha})`;
  c.fill();

  c.restore();
});
